mapper.select:
SELECT p.id, p.release_id, p.base_version, p.file_name, p.stored_file_name, p.sha256, p.file_size, p.created_at
FROM app_release_patches p
JOIN app_releases r ON r.id = p.release_id
WHERE r.version = #{version}
  AND p.base_version = #{baseVersion}

mapper.update:
UPDATE app_releases
SET active = FALSE
WHERE id = #{id}

UPDATE app_releases
SET active = TRUE
WHERE id = #{id}
